def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    DIGITS = "0123456789"

    def amount(tok: str):
        if tok and all(c in DIGITS for c in tok):
            return int(tok)
        return None

    def save(names):
        return [(n, list(accounts[n]) if n in accounts else None) for n in names]

    accounts: dict[str, list] = {}  # name -> [balance, frozen]
    history: list[list[tuple[str, object]]] = []  # undo records of successful ops
    rejected: list[int] = []

    for idx, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0]
        n = len(t)
        record = None

        if verb == "undo":
            if n == 1 and history:
                for name, prev in history.pop():
                    if prev is None:
                        accounts.pop(name, None)
                    else:
                        accounts[name] = prev
            else:
                rejected.append(idx)
            continue

        if verb == "open" and n == 3:
            name, amt = t[1], amount(t[2])
            if amt is not None and name not in accounts:
                record = save([name])
                accounts[name] = [amt, False]

        elif verb == "deposit" and n == 3:
            name, amt = t[1], amount(t[2])
            if amt is not None and amt > 0 and name in accounts:
                record = save([name])
                accounts[name][0] += amt

        elif verb == "withdraw" and n == 3:
            name, amt = t[1], amount(t[2])
            if (amt is not None and amt > 0 and name in accounts
                    and not accounts[name][1] and accounts[name][0] >= amt):
                record = save([name])
                accounts[name][0] -= amt

        elif verb == "transfer" and n == 4:
            src, dst, amt = t[1], t[2], amount(t[3])
            if (amt is not None and amt > 0 and src != dst
                    and src in accounts and dst in accounts
                    and not accounts[src][1] and accounts[src][0] >= amt):
                record = save([src, dst])
                accounts[src][0] -= amt
                accounts[dst][0] += amt

        elif verb == "freeze" and n == 2:
            name = t[1]
            if name in accounts and not accounts[name][1]:
                record = save([name])
                accounts[name][1] = True

        elif verb == "unfreeze" and n == 2:
            name = t[1]
            if name in accounts and accounts[name][1]:
                record = save([name])
                accounts[name][1] = False

        if record is None:
            rejected.append(idx)
        else:
            history.append(record)

    return {name: state[0] for name, state in accounts.items()}, rejected
